def max_sum_increasing_subseq(a, n, index, k):
    """Write a function to find the maximum sum of increasing subsequence from prefix till ith index and also including a given kth element which is after i, i.e., k > i ."""
    if not a or n <= 0:
        return 0
    n = min(n, len(a))
    if k < 0 or k >= n:
        return 0
    if index < 0:
        return a[k]
    if index >= n:
        index = n - 1
    # msis[i] = maximum sum of increasing subsequence ending at i (including a[i])
    # using only elements within prefix 0..index.
    msis = [0] * (index + 1)
    for i in range(index + 1):
        msis[i] = a[i]
        for j in range(i):
            if a[j] < a[i] and msis[j] + a[i] > msis[i]:
                msis[i] = msis[j] + a[i]
    result = a[k]
    # Only positions < k can precede k in a subsequence.
    limit = min(index, k - 1) if k > 0 else -1
    for i in range(limit + 1):
        if a[i] < a[k] and msis[i] + a[k] > result:
            result = msis[i] + a[k]
    return result
